import assert from 'node:assert/strict';
import {ToyRoomBattle} from '../src/js/toy-room/ToyRoomBattle.js';
import {ARENA_ENEMIES} from '../src/js/toy-room/ArenaEnemies.js';
import {ARENA_TUNING,ArenaPlayerController} from '../src/js/toy-room/ArenaPlayerController.js';
import {arenaEnemyContact} from '../src/js/toy-room/ArenaCombatContact.js';
import {selectArenaEnemyAttack} from '../src/js/toy-room/ArenaEnemyAI.js';
import {beginArenaPlayerAttack,updateArenaPlayerAnimation} from '../src/js/toy-room/ArenaPlayerAnimation.js';
function make(actor,corner=false) {
 const r={player:{x:430,facing:'right',animTime:0},keysDown:{},gamepadState:{},touchState:{},tutorial:{},furniture:[],clearInput(){this.keysDown={};},story:{state:{swordEquipped:true,attackElapsed:0},attack(){if(this.state.attackElapsed>0)return false;this.state.attackElapsed=18;this.state.attackDirection=r.player.facing==='left'?-1:1;return true;}}};
 const b=new ToyRoomBattle(r,{loadAssets:false});b.tuning=ARENA_TUNING;b.playerController=new ArenaPlayerController();b.presentation={enemies:ARENA_ENEMIES,enemyContact:arenaEnemyContact,onSound(sound){if(sound==='player_attack')beginArenaPlayerAttack(b.state,r.story.state.attackDirection);},updateAnimation(dt){updateArenaPlayerAnimation(b.state,r.player,dt);}};b.activate();if(actor){b.state.index=['train','robot','dinosaur','bear'].indexOf(actor);b.spawn();b.state.transition=null;if(corner){b.state.enemy.x=1440-ARENA_ENEMIES[actor].bodyWidth/2;r.player.x=b.state.enemy.x-b.getEnemyCollisionDistance(actor);}}
 return b;
}
function play({actor,policy='smart',interval=1,dt=1,corner=false,offset=0,restore=false}){
 const b=make(actor,corner);let f=offset;const counts={};
 for(;f<18000&&b.state.mode==='BATTLE';f+=dt){
 const s=b.state,e=s.enemy,p=b.room.player,side=e.x>=p.x?1:-1,range=Math.max(b.tuning.swordRange,b.getEnemyCollisionDistance(e.actor)+40);
 b.room.keysDown={};if(!s.transition){
 const toward=side>0?'ArrowRight':'ArrowLeft';
 if(policy==='spam'){b.room.keysDown[toward]=true;if(Math.floor(f)%interval===0)b.attack();}
 else {
 const contact=['Laser Beam','Rocket Punch'].includes(e.attack);
 if(Math.abs(e.x-p.x)>range-12)b.room.keysDown[toward]=true;
 if(e.state==='ATTACK'){
 const end=e.attack==='Toy Leap'?96:72;
 if(contact&&e.elapsed<end)b.room.keysDown.ArrowDown=true;
 if(!contact){const jumpAt=e.attack==='Toy Leap'?60:30;if(e.elapsed>=jumpAt&&e.elapsed<jumpAt+5&&s.jump===0)b.room.keysDown.ArrowUp=true;}
 if(e.elapsed>=end&&s.jump<85)b.attack();
 }else if(e.state!=='HIT'&&e.state!=='ENRAGE'&&Math.abs(e.x-p.x)<range-5&&s.jump<85)b.attack();
 }
 }
 b.update(dt);if(restore&&Math.floor(f)%97===0){const saved=b.snapshot();b.restore(saved);}
 }
 for(const a of ['train','robot','dinosaur','bear'])counts[a]={acertos:b.state.history.filter(x=>x.event==='PLAYER_HIT'&&x.enemy===a).length,danos:b.state.history.filter(x=>x.event==='ENEMY_HIT'&&x.enemy===a).length,bloqueios:b.state.history.filter(x=>x.event==='SWORD_BLOCKED'&&x.enemy===a).length};
 return {actor,policy,interval,dt,corner,offset,restore,resultado:b.state.mode,hp:b.state.player.hp,segundos:+((f-offset)/60).toFixed(2),counts};
}

let checked=0;
for(const actor of ['robot','dinosaur','bear'])for(const interval of [1,6,12,24,36])for(const corner of [false,true])for(const dt of [.5,1,3]){
 const result=play({actor,policy:'spam',interval,corner,dt,offset:7});
 if(result.resultado!=='DEFEAT')console.log('FALHA',JSON.stringify(result));
 assert.equal(result.resultado,'DEFEAT','Insistência deve perder: '+JSON.stringify(result));checked++;
}
for(const dt of [.5,1,3])for(const actor of [undefined,'robot','dinosaur','bear'])for(const corner of (actor?[false,true]:[false])){
 const result=play({actor,policy:'smart',dt,corner,restore:true});console.log(JSON.stringify(result));assert.equal(result.resultado,'VICTORY','Esquiva e contra-ataque devem vencer');checked++;
}

for(const actor of ['robot','dinosaur','bear']){
 const b=make(actor);const e=b.state.enemy,r=b.room,s=b.state;
 e.x=900;r.player.x=e.x-b.getEnemyCollisionDistance(actor)-5;r.player.facing='right';r.keysDown.ArrowRight=true;e.state='APPROACH';b.attack();b.update(6);
 assert.equal(e.evasions,1,'Evasão reage à antecipação');assert.ok(Math.abs(e.x-r.player.x)>Math.max(b.tuning.swordRange,b.getEnemyCollisionDistance(actor)+40),'Evasão sai efetivamente do alcance');assert.equal(e.hp,e.maxHp);
 e.state='ATTACK';e.attack=actor==='robot'?'Laser Beam':actor==='dinosaur'?'Rush':'Belly Charge';e.elapsed=20;e.landed=false;e.responseAttack=true;
 r.player.x=e.x-b.getEnemyCollisionDistance(actor)-5;s.cooldown=0;s.attackTime=0;r.story.state.attackElapsed=0;s.player.hp=2;b.attack();b.update(6);
 assert.equal(e.hp,e.maxHp,'Resposta protegida não transfere coração');assert.equal(s.player.hp,2,'Golpe bloqueado não cura');assert.equal(e.state,'ATTACK','Ataque inimigo não é interrompido');assert.ok(s.history.some(x=>x.event==='SWORD_BLOCKED'));
 const saved=b.snapshot();b.restore(saved);assert.deepEqual(b.snapshot(),saved,'Resposta protegida persiste sem duplicar eventos');
 const current=b.state.enemy;current.elapsed=72;current.landed=false;current.responseAttack=true;b.state.cooldown=0;b.state.attackTime=0;r.story.state.attackElapsed=0;r.keysDown={};b.attack();b.update(6);
 assert.equal(current.hp,current.maxHp-1,'Recuperação permite dano');assert.equal(b.state.player.hp,3,'Contra-ataque válido cura');
 b.state.playerHitTime=10;b.state.cooldown=0;r.story.state.attackElapsed=0;assert.equal(b.attack(),false,'Reação de dano impede novo ataque');
 b.state.playerHitTime=0;current.state='HIT';current.elapsed=24;b.update(1);assert.equal(current.state,'ATTACK','Após dano, inicia resposta com preparação completa');assert.ok(current.responseAttack);assert.equal(current.elapsed,0);
}
const adaptive=make('dinosaur');adaptive.state.playerBehavior={samples:180,jumping:0,attacking:1,distant:0};adaptive.state.enemy.lastAIChoice='Rush';adaptive.state.enemy.recentAIChoices=['Bite','Rush'];
assert.equal(selectArenaEnemyAttack(adaptive,200,['Bite','Rush']),'Rush','Utilidade pode superar repetição, sem sequência obrigatória');
console.log('APROVADO: '+checked+' percursos; ataque repetido perde e esquiva vence; evasão efetiva, bloqueio sem cura, resposta após dano, recuperação vulnerável e save/load.');
export {make,play};
